import 'package:flutter/material.dart';
import 'package:url_launcher/url_launcher.dart';

import '../../../themes/stack_colors.dart';
import '../../../utilities/text_styles.dart';
import '../../../utilities/util.dart';
import '../../open_crypto_pay/open_crypto_pay_send_handler.dart';

/// Labeled business details of an OpenCryptoPay recipient.
class OpenCryptoPayBusinessDetails extends StatelessWidget {
  const OpenCryptoPayBusinessDetails({super.key, required this.details});

  final List<BusinessDetail> details;

  @override
  Widget build(BuildContext context) {
    final isDesktop = Util.isDesktop;
    final headerStyle = isDesktop
        ? STextStyles.desktopTextExtraExtraSmall600(context)
        : STextStyles.w600_12(context);
    final labelStyle = isDesktop
        ? STextStyles.desktopTextExtraExtraSmall(context)
        : STextStyles.smallMed12(context);
    final valueStyle = isDesktop
        ? STextStyles.desktopTextExtraExtraSmall(context).copyWith(
            color: Theme.of(context).extension<StackColors>()!.textDark,
          )
        : STextStyles.itemSubtitle12(context);
    final linkStyle = valueStyle.copyWith(
      color: STextStyles.link2(context).color,
    );

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      mainAxisSize: MainAxisSize.min,
      children: [
        Text("Business", style: headerStyle),
        for (final detail in details) ...[
          const SizedBox(height: 8),
          Text(detail.label, style: labelStyle),
          const SizedBox(height: 2),
          if (detail.uri case final uri?)
            SelectableText(
              detail.value,
              style: linkStyle,
              onTap: () => launchUrl(uri, mode: LaunchMode.externalApplication),
            )
          else
            SelectableText(detail.value, style: valueStyle),
        ],
      ],
    );
  }
}
